// Builds firestore.rules from firestore.rules.template using ALLOWED_EMAILS (comma-separated) from the
// environment or .env. The generated file is git-ignored so your emails are not committed.
import 'dotenv/config';
import { readFileSync, writeFileSync } from 'node:fs';

const raw = process.env.ALLOWED_EMAILS || '';
const emails = raw
  .split(',')
  .map((e) => e.trim().toLowerCase())
  .filter(Boolean);

if (emails.length === 0) {
  console.error('ALLOWED_EMAILS está vacío. Defínelo en .env, por ejemplo: ALLOWED_EMAILS="ana@gmail.com,juan@gmail.com"');
  process.exit(1);
}
const invalid = emails.filter((e) => !/^[^\s@'"\\]+@[^\s@'"\\]+\.[^\s@'"\\]+$/.test(e));
if (invalid.length) {
  console.error(`Correos inválidos en ALLOWED_EMAILS: ${invalid.join(', ')}`);
  process.exit(1);
}
if (emails.length > 2) {
  console.warn(`Aviso: ALLOWED_EMAILS tiene ${emails.length} correos (se esperaban 2).`);
}

const template = readFileSync(new URL('../firestore.rules.template', import.meta.url), 'utf8');
const out = template
  .replace('__ALLOWED_EMAILS__', emails.map((e) => `'${e}'`).join(', '))
  .replace('// GENERATED FILE SOURCE: edit firestore.rules.template, then run `npm run firebase:rules`', '// GENERATED by scripts/build-firestore-rules.mjs from firestore.rules.template – do not edit by hand.');
writeFileSync(new URL('../firestore.rules', import.meta.url), out);
console.log(`firestore.rules generado para: ${emails.join(', ')}`);

// `npm run deploy:rules` → also publish the rules to your Firebase project.
if (process.argv.includes('--deploy')) {
  const { spawnSync } = await import('node:child_process');
  const project = process.env.FIREBASE_PROJECT_ID || process.env.VITE_FIREBASE_PROJECT_ID;
  if (!project) {
    console.error('Falta FIREBASE_PROJECT_ID en .env');
    process.exit(1);
  }
  const r = spawnSync('npx', ['-y', 'firebase-tools@15', 'deploy', '--only', 'firestore:rules', '--project', project], {
    stdio: 'inherit',
    shell: process.platform === 'win32',
  });
  process.exit(r.status ?? 1);
}
